        0x2bb45a92, 0x5cb36a04, 0xc2d7ffa7, 0xb5d0cf31, 0x2cd99e8b, 0x5bdeae1d,
        0x9b64c2b0, 0xec63f226, 0x756aa39c, 0x026d930a, 0x9c0906a9, 0xeb0e363f,
        0x72076785, 0x05005713, 0x95bf4a82, 0xe2b87a14, 0x7bb12bae, 0x0cb61b38,
        0x92d28e9b, 0xe5d5be0d, 0x7cdcefb7, 0x0bdbdf21, 0x86d3d2d4, 0xf1d4e242,
        0x68ddb3f8, 0x1fda836e, 0x81be16cd, 0xf6b9265b, 0x6fb077e1, 0x18b74777,
        0x88085ae6, 0xff0f6a70, 0x66063bca, 0x11010b5c, 0x8f659eff, 0xf862ae69,
        0x616bffd3, 0x166ccf45, 0xa00ae278, 0xd70dd2ee, 0x4e048354, 0x3903b3c2,
        0xa7672661, 0xd06016f7, 0x4969474d, 0x3e6e77db, 0xaed16a4a, 0xd9d65adc,
        0x40df0b66, 0x37d83bf0, 0xa9bcae53, 0xdebb9ec5, 0x47b2cf7f, 0x30b5ffe9,
        0xbdbdf21c, 0xcabac28a, 0x53b39330, 0x24b4a3a6, 0xbad03605, 0xcdd70693,
        0x54de5729, 0x23d967bf, 0xb3667a2e, 0xc4614ab8, 0x5d681b02, 0x2a6f2b94,
        0xb40bbe37, 0xc30c8ea1, 0x5a05df1b, 0x2d02ef8d};

    const auto* bytes = static_cast<const uint8_t*>(data);
    uint32_t crc = ~0U;
    while (size--)
    {
        crc = table[(crc ^ *bytes++) & 0xff] ^ (crc >> 8);
    }
    return crc ^ ~0U;
}

void setCrc(uint8_t* buffer, size_t length)
{
    if (length < 4)
    {
        return;
    }

    const uint32_t crc = crc32(buffer, length - 4);
    buffer[length - 4] = static_cast<uint8_t>(crc & 0xFF);
    buffer[length - 3] = static_cast<uint8_t>((crc >> 8) & 0xFF);
    buffer[length - 2] = static_cast<uint8_t>((crc >> 16) & 0xFF);
    buffer[length - 1] = static_cast<uint8_t>((crc >> 24) & 0xFF);
}

void fillInitResponse(uint8_t* buffer, size_t length, bool ok)
{
    std::memset(buffer, 0, length);
    if (length < 4)
    {
        return;
    }
    buffer[1] = 0x55;
    if (ok)
    {
        buffer[2] = 0x5A;
        buffer[3] = 0xA5;
    }
    setCrc(buffer, length);
}

void fillFirmwareNotInRecovery(uint8_t* buffer, size_t length)
{
    std::memset(buffer, 0, length);
}

void fillWriteResponse(uint8_t* buffer, size_t length, uint8_t cmd)
{
    std::memset(buffer, 0, length);
    if (length < 3)
    {
        return;
    }
    buffer[1] = cmd;
    buffer[2] = 0;
    setCrc(buffer, length);
}

int (*realOpen64)(const char*, int, ...) = nullptr;
int (*realClose)(int) = nullptr;
int (*realIoctl)(int, unsigned long, void*) = nullptr;

bool isFakeFd(int fd)
{
    return fakeFdToBus.contains(fd);
}

