extern "C" int open64(const char* path, int flags, ...)
{
    if (!realOpen64)
    {
        realOpen64 = reinterpret_cast<int (*)(const char*, int, ...)>(
            dlsym(RTLD_NEXT, "open64"));
    }

    constexpr std::string_view prefix = "/dev/i2c-";
    if (std::strncmp(path, prefix.data(), prefix.size()) == 0)
    {
        const char* suffix = path + prefix.size();
        if (*suffix == '\0')
        {
            errno = EINVAL;
            return -1;
        }

        char* end = nullptr;
        errno = 0;
        const long parsedBus = std::strtol(suffix, &end, 10);
        if (errno != 0 || *end != '\0' || parsedBus < 0 ||
            parsedBus > std::numeric_limits<int>::max())
        {
            errno = EINVAL;
            return -1;
        }

        const int bus = static_cast<int>(parsedBus);
        if (bus == 8)
        {
            errno = EIO;
            return -1;
        }
        const int fakeFd = 1000 + bus;
        fakeFdToBus[fakeFd] = bus;
        return fakeFd;
    }

    va_list args;
    va_start(args, flags);
    const int mode = ((flags & O_CREAT) != 0) ? va_arg(args, int) : 0;
    va_end(args);
    if ((flags & O_CREAT) != 0)
    {
        return realOpen64(path, flags, mode);
    }
    return realOpen64(path, flags);
}

extern "C" int close(int fd)
{
    if (!realClose)
    {
        realClose = reinterpret_cast<int (*)(int)>(dlsym(RTLD_NEXT, "close"));
    }
    if (isFakeFd(fd))
    {
        fakeFdToBus.erase(fd);
        return 0;
    }
    return realClose(fd);
}

extern "C" int ioctl(int fd, unsigned long request, ...)
{
    va_list args;
    va_start(args, request);
    auto* data = va_arg(args, void*);
    va_end(args);

    if (!realIoctl)
    {
        realIoctl = reinterpret_cast<int (*)(int, unsigned long, void*)>(
            dlsym(RTLD_NEXT, "ioctl"));
    }

    if (!isFakeFd(fd) || request != I2C_RDWR)
    {
        return realIoctl(fd, request, data);
    }

    auto* rdwr = static_cast<i2c_rdwr_ioctl_data*>(data);
    const int bus = fakeFdToBus.at(fd);
    auto& state = busStates[bus];

    if (rdwr->nmsgs == 1)
    {
        const uint8_t cmd = rdwr->msgs[0].buf[0];
        state.lastCmd = cmd;
        if (cmd == 0x55)
        {
            state.initCalls++;
        }
        if (bus == 1 && cmd == 0xC0)
        {
            errno = EIO;
            return -1;
        }
        if (bus == 4 && cmd == 0x66 && !state.performFailureInjected)
        {
            state.performFailureInjected = true;
            errno = EIO;
            return -1;
        }
        return 1;
    }

    if (rdwr->nmsgs == 2)
    {
        auto* buffer = rdwr->msgs[1].buf;
        const auto length = static_cast<size_t>(rdwr->msgs[1].len);

        if (state.lastCmd == 0x55)
        {
            if (bus == 2)
            {
                fillFirmwareNotInRecovery(buffer, length);
            }
            else if (bus == 3)
            {
                fillInitResponse(buffer, length, false);
            }
            else if (bus == 5)
            {
                if (state.initCalls == 1)
                {
                    fillInitResponse(buffer, length, true);
                }
                else
                {
                    fillFirmwareNotInRecovery(buffer, length);
                }
            }
            else if (bus == 6)
            {
                fillInitResponse(buffer, length, true);
            }
            else if (bus == 7)
            {
                if (state.initCalls == 1)
                {
                    fillInitResponse(buffer, length, true);
                }
                else
                {
                    fillInitResponse(buffer, length, false);
                }
            }
            else
            {
                fillInitResponse(buffer, length, true);
            }
            return 2;
        }

        if (state.lastCmd == 0x66 || state.lastCmd == 0x65 ||
            state.lastCmd == 0x67)
        {
            fillWriteResponse(buffer, length, state.lastCmd);
            return 2;
        }
    }

    errno = EINVAL;
    return -1;
}

